//
// Everything downstream assumes git: worktrees, base commits, diffs, and
// adoption's fast-forward. Pointing at a folder that is not a repository is a
// normal first-run case for someone who has been editing without one, and the
// front door used to explain the requirement and then stop.
//
// This offers the step instead. Known generated directories can be ignored and
// verified mechanically; secrets, built binaries, and ambiguous folder shapes
// still refuse rather than guess. There is no "commit everything and hope"
// path, because the first commit is what every later diff is measured against.

#[derive(serde::Serialize)]
pub struct GitReadiness {
    /// Whether the path is there at all.
    ///
    /// Reported rather than thrown. A missing path used to come back as an
    /// error, so the surface fell through to its git branch and announced "This
    /// folder is not tracked by git yet" about a folder that did not exist,
    /// with the real answer in red underneath and step one ticked above.
    pub exists: bool,
    /// Whether it is a directory. A file is not a project.
    pub is_directory: bool,
    pub is_repo: bool,
    /// What the folder appears to hold.
    pub content: FolderContent,
    /// Examples of what led to that reading, so a refusal can name them.
    pub saw: Vec<String>,
    /// The folder has no files yet, so the first commit must be empty.
    pub starts_empty: bool,
    /// Files that would be committed, so the offer can name them.
    pub would_commit: Vec<String>,
    /// Generated top-level directories Hivemind can safely add to .gitignore.
    pub would_ignore: Vec<String>,
    /// Why Hivemind will not initialise this folder, when it will not.
    pub refusal: Option<String>,
}

/// Names that mean "this folder holds something a first commit must not take".
///
/// Kept, but no longer the whole check -- see `shape_refusal`. A list of names
/// can only ever refuse the secrets somebody thought to list, and the case that
/// actually mattered was not a secret at all.
const NEVER_COMMIT: [&str; 6] = [
    ".env",
    ".env.local",
    "id_rsa",
    "credentials.json",
    "secrets.json",
    ".npmrc",
];

/// Directories whose contents are installed or generated, never authored.
const NOT_AUTHORED_DIRS: [&str; 13] = [
    "node_modules",
    "vendor",
    "target",
    "__pycache__",
    ".venv",
    "venv",
    "bower_components",
    "Pods",
    "dist",
    "build",
    "coverage",
    ".next",
    "out",
];

/// Extensions that mean "this file is built, not written".
const BINARY_EXTENSIONS: [&str; 16] = [
    "exe", "dll", "so", "dylib", "msi", "pdb", "bin", "obj", "o", "a", "lib", "class", "jar",
    "wasm", "node", "pyd",
];

/// Extensions that mean "somebody wrote this".
///
/// Deliberately generous and deliberately not exhaustive: the question it
/// answers is "does this folder contain authored work at all", and a folder
/// with even one recognised source file passes. Being wrong in the permissive
/// direction costs a refusal that should not have happened; being wrong in the
/// other direction commits somebody's build output forever.
const SOURCE_EXTENSIONS: [&str; 40] = [
    "ts", "tsx", "js", "jsx", "mjs", "cjs", "rs", "py", "rb", "go", "java", "kt", "swift", "c",
    "h", "cc", "cpp", "hpp", "cs", "php", "ex", "exs", "scala", "clj", "hs", "ml", "lua", "sh",
    "ps1", "sql", "html", "css", "scss", "vue", "svelte", "json", "toml", "yaml", "yml",
    "gradle",
];

/// Prose and documents. Authored, but not code.
///
/// `txt` and `md` used to sit in SOURCE_EXTENSIONS, and `txt` is why a folder of
/// holiday photos with a shopping list in it read as a project and was offered a
/// first commit. A folder of documents may still be a real project -- a docs
/// repository is a project -- so this is not a refusal on its own. It is a fact
/// the surface has to be able to state.
const DOCUMENT_EXTENSIONS: [&str; 6] = ["md", "txt", "rst", "adoc", "pdf", "docx"];

/// Photos, video and audio. Not authored code under any reading.
///
/// Absent entirely before, so `holiday.jpg` was not merely allowed -- it was
/// invisible. A folder whose recognised content is media, with no code in it,
/// is not a project to work on, and the refusal can now name what it saw.
const MEDIA_EXTENSIONS: [&str; 16] = [
    "jpg", "jpeg", "png", "gif", "bmp", "tif", "tiff", "heic", "webp", "mp4", "mov", "avi", "mkv",
    "mp3", "wav", "flac",
];

/// Whether this folder has the SHAPE of a project somebody means to start
/// tracking, rather than whether it happens to contain one of six filenames.
///
/// The list-based check let the worst case straight through. The desktop used
/// to open `"."` on launch, which for an installed app is its own installation
/// directory -- and an install directory holds no `.env`, so `git init && git
/// add -A && commit` would have taken the executable, the DLLs and a bundled
/// `node_modules` into a first commit that every later diff is measured
/// against. A list can only refuse what somebody thought to list.
///
/// The shapes that require human judgment are refused, and each is stated as
/// what it IS rather than as a rule number. Known generated directories are
/// handled separately as a mechanical preparation, not flattened into this
/// human-judgment path.
/// What this folder appears to hold. Reported, not inferred at the call site.
#[derive(serde::Serialize, PartialEq, Eq, Debug, Clone, Copy)]
#[serde(rename_all = "snake_case")]
pub enum FolderContent {
    /// Nothing at all. A valid greenfield project.
    Empty,
    /// Code somebody wrote.
    Source,
    /// Prose and documents, and no code.
    Documents,
    /// Photos, video or audio, and no code.
    Media,
    /// Built programs: an install directory or a build output.
    Built,
    /// Files, but nothing recognised.
    Unrecognised,
}

/// What the folder holds, and examples of what was seen.
///
/// One classification, computed once, from which the heading, the step tick, the
/// git offer and the commit preview are all derived. Before this each of those
/// assumed a project: a missing path, a file and a folder of photos all got the
/// same "Set up this project" screen with step one ticked.
fn classify_content(root: &Path, entries: &[String]) -> (FolderContent, Vec<String>) {
    if entries.is_empty() {
        return (FolderContent::Empty, Vec::new());
    }

    let mut binaries: Vec<String> = Vec::new();
    let mut media: Vec<String> = Vec::new();
    let mut documents: Vec<String> = Vec::new();
    let mut has_source = false;

    for name in entries {
        let path = root.join(name);
        if path.is_dir() {
            // A directory is not walked. Depth would make this slow on a large
            // tree for no gain: the shapes being refused are all visible at the
            // top level, and a folder whose only source lives three levels down
            // still reads as a project by its top-level files.
            continue;
        }
        let extension = path
            .extension()
            .map(|value| value.to_string_lossy().to_lowercase())
            .unwrap_or_default();
        if BINARY_EXTENSIONS.iter().any(|needle| extension == *needle) {
            binaries.push(name.clone());
        } else if MEDIA_EXTENSIONS.iter().any(|needle| extension == *needle) {
            media.push(name.clone());
        } else if DOCUMENT_EXTENSIONS.iter().any(|needle| extension == *needle) {
            documents.push(name.clone());
        }
        if SOURCE_EXTENSIONS.iter().any(|needle| extension == *needle) {
            has_source = true;
        }
    }

    // Source wins over everything: a real project with a few images and a
    // README is a project, and refusing it would be the costly direction.
    if has_source {
        return (FolderContent::Source, Vec::new());
    }
    let examples = |mut names: Vec<String>| -> Vec<String> {
        names.sort();
        names.truncate(4);
        names
    };
    if !binaries.is_empty() {
        return (FolderContent::Built, examples(binaries));
    }
    if !media.is_empty() {
        return (FolderContent::Media, examples(media));
    }
    if !documents.is_empty() {
        return (FolderContent::Documents, examples(documents));
    }
    (FolderContent::Unrecognised, Vec::new())
}

/// Why Hivemind will not initialise this folder, when it will not.
///
/// Says what it SAW. A refusal that names nothing leaves a person guessing at
/// which of their files caused it.
fn shape_refusal(content: FolderContent, saw: &[String]) -> Option<String> {
    match content {
        // A truly empty directory is a valid greenfield project. There is
        // nothing ambiguous to inspect or accidentally commit, and Git supports
        // an explicit empty base commit for exactly this case.
        FolderContent::Empty | FolderContent::Source => None,
        // Documents with no code may still be a real project -- a documentation
        // repository is one -- so this is stated rather than refused.
        FolderContent::Documents => None,
        FolderContent::Built => Some(format!(
            "This folder holds built programs rather than source ({}). That looks like an installed application or a build output directory, not a project to work on. Choose the folder your source code lives in.",
            saw.join(", ")
        )),
        FolderContent::Media => Some(format!(
            "This folder holds pictures, video or audio ({}) and no source code. Hivemind would have to make a first commit of these files, and a first commit cannot be un-made without rewriting history. Choose the folder your source code lives in.",
            saw.join(", ")
        )),
        FolderContent::Unrecognised => Some(
            "This folder has no source files in it, so there is nothing for Hivemind to work on yet. Choose the folder your project lives in."
                .to_string(),
        ),
    }
}

#[tauri::command]
pub async fn inspect_git_readiness(project_path: String) -> Result<GitReadiness, String> {
    let root = std::path::Path::new(&project_path);

    // Classify first, and report it. Everything the surface says downstream --
    // the heading, the step tick, whether git is offered, what a commit would
    // include -- derives from this rather than assuming a project.
    if !root.exists() {
        return Ok(GitReadiness {
            exists: false,
            is_directory: false,
            is_repo: false,
            content: FolderContent::Empty,
            saw: Vec::new(),
            starts_empty: false,
            would_commit: Vec::new(),
            would_ignore: Vec::new(),
            refusal: Some(
                "There is nothing at that path. Check it, or choose a folder.".to_string(),
            ),
        });
    }
    if !root.is_dir() {
        return Ok(GitReadiness {
            exists: true,
            is_directory: false,
            is_repo: false,
            content: FolderContent::Unrecognised,
            saw: root
                .file_name()
                .map(|name| vec![name.to_string_lossy().to_string()])
                .unwrap_or_default(),
            starts_empty: false,
            would_commit: Vec::new(),
            would_ignore: Vec::new(),
            refusal: Some(
                "That is a file, not a folder. Hivemind works inside a project folder -- choose the folder this file lives in.".to_string(),
            ),
        });
    }
    if root.join(".git").exists() {
        return Ok(GitReadiness {
            exists: true,
            is_directory: true,
            is_repo: true,
            content: FolderContent::Source,
            saw: Vec::new(),
            starts_empty: false,
            would_commit: Vec::new(),
            would_ignore: Vec::new(),
            refusal: None,
        });
    }

    let mut would_commit = Vec::new();
    let mut would_ignore = Vec::new();
    let mut dangerous = Vec::new();
    // Every top-level name, including the ones the display list hides. The
    // shape check has to see `node_modules` -- it is the whole reason the check
    // exists, and filtering it out of the list first is what let an install
    // directory through. `would_commit` is what a person is SHOWN; `present` is
    // what is actually there.
    let mut present = Vec::new();
    let entries = std::fs::read_dir(root)
        .map_err(|error| format!("could not read that folder: {error}"))?;
    for entry in entries.flatten() {
        let name = entry.file_name().to_string_lossy().to_string();
        if name == ".git" || name == ".hivemind" {
            continue;
        }
        present.push(name.clone());
        if entry.path().is_dir() && NOT_AUTHORED_DIRS.iter().any(|dir| name == *dir) {
            would_ignore.push(name);
            continue;
        }
        if NEVER_COMMIT.iter().any(|needle| name == *needle) {
            dangerous.push(name.clone());
        }
        would_commit.push(name);
    }
    would_commit.sort();
    would_ignore.sort();

    // Refuse rather than guess. A .env in the folder is not something to decide
    // about on somebody's behalf -- and a first commit cannot be un-made
    // without rewriting history, which is exactly what a person who has never
    // used git cannot be asked to do.
    //
    // Named secrets first, because that refusal names the actual file and is
    // the more useful sentence when both apply.
    let (content, saw) = classify_content(root, &present);
    let refusal = if !dangerous.is_empty() {
        dangerous.sort();
        Some(format!(
            "This folder holds {} that should probably never be committed. Hivemind will not decide that for you: add a .gitignore, or set the repository up yourself, and open it again.",
            dangerous.join(", ")
        ))
    } else {
        shape_refusal(content, &saw)
    };

    Ok(GitReadiness {
        exists: true,
        is_directory: true,
        is_repo: false,
        content,
        saw,
        starts_empty: present.is_empty(),
        would_commit,
        would_ignore,
        refusal,
    })
}

fn add_generated_ignores(root: &Path, entries: &[String]) -> Result<(), String> {
    if entries.is_empty() {
        return Ok(());
    }
    let path = root.join(".gitignore");
    let existing = match std::fs::read_to_string(&path) {
        Ok(value) => value,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => String::new(),
        Err(error) => return Err(format!("could not read .gitignore: {error}")),
    };
    let mut next = existing.clone();
    if !next.is_empty() && !next.ends_with('\n') {
        next.push('\n');
    }
    let mut added_header = false;
    for entry in entries {
        let rule = format!("{entry}/");
        if existing.lines().any(|line| line.trim() == rule) {
            continue;
        }
        if !added_header {
            next.push_str("# Added by Hivemind before the first commit.\n");
            added_header = true;
        }
        next.push_str(&rule);
        next.push('\n');
    }
    if next != existing {
        std::fs::write(&path, next).map_err(|error| format!("could not update .gitignore: {error}"))?;
    }
    Ok(())
}

/// A failed setup names what it left behind, in a code the client branches
/// on. Control flow never depends on message text: "the folder was put back"
/// and "something remains" are different facts produced by the same failure,
/// and the client's copy must not claim the first while the second is true --
/// which is exactly what "Nothing changed." did for every failure (A-07).
#[derive(Debug, Clone, serde::Serialize)]
pub struct GitSetupFailure {
    /// "nothing_changed": the folder is byte-identical to how the action
    /// found it. "partial_state": rollback could not complete, or completion
    /// could not be confirmed.
    pub code: &'static str,
    pub message: String,
    /// The paths still on disk when `code` is "partial_state". Empty otherwise.
    pub remaining: Vec<String>,
}

impl GitSetupFailure {
    fn untouched(message: String) -> Self {
        Self {
            code: "nothing_changed",
            message,
            remaining: Vec::new(),
        }
    }
}

/// Put the folder back exactly as `perform_git_setup` found it. Returns the
/// names it could NOT put back; an empty list means the folder is untouched.
fn undo_git_setup(
    root: &Path,
    original_gitignore: Option<String>,
    created_git_dir: bool,
) -> Vec<String> {
    let mut remaining = Vec::new();
    let git_dir = root.join(".git");
    /* Only a repository THIS call created is removed. `created_git_dir` was
       measured before the first mutation, so a pre-existing `.git` -- whatever
       shape it is in -- is never this function's to delete. */
    if created_git_dir && git_dir.exists() {
        let _ = std::fs::remove_dir_all(&git_dir);
        if git_dir.exists() {
            remaining.push(".git".to_string());
        }
    }
    let ignore_path = root.join(".gitignore");
    let restored = match original_gitignore {
        Some(content) => std::fs::write(&ignore_path, content).is_ok(),
        None => match std::fs::remove_file(&ignore_path) {
            Ok(()) => true,
            Err(error) => error.kind() == std::io::ErrorKind::NotFound,
        },
    };
    if !restored {
        remaining.push(".gitignore".to_string());
    }
    remaining
}

/// The mutation sequence behind one-click git setup, with the command runner
/// injected so a test can fail any single step against a real folder and hold
/// the rollback to its claim.
///
/// The invariant: this either completes fully, or the folder is left
/// byte-identical to how it was found -- and when even that cannot be
/// guaranteed, the failure says exactly what remains instead of claiming
/// cleanliness it cannot prove.
fn perform_git_setup(
    root: &Path,
    would_ignore: &[String],
    run: &dyn Fn(&[&str]) -> Result<(), String>,
) -> Result<(), GitSetupFailure> {
    /* Captured BEFORE the first mutation, so "nothing changed" is a
       measurement against this state rather than a hope. */
    let original_gitignore = match std::fs::read_to_string(root.join(".gitignore")) {
        Ok(value) => Some(value),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => None,
        Err(error) => {
            return Err(GitSetupFailure::untouched(format!(
                "could not read .gitignore: {error}"
            )))
        }
    };
    let git_dir_existed = root.join(".git").exists();

    let sequence = || -> Result<(), String> {
        add_generated_ignores(root, would_ignore)?;
        run(&["init"])?;
        for entry in would_ignore {
            run(&["check-ignore", "--quiet", "--", entry])?;
        }
        run(&["add", "-A"])?;
        // A message that says what it did and why, because this commit is the base
        // every later diff is measured against and somebody will read it later
        // wondering where it came from.
        run(&[
            "-c",
            "user.name=Hivemind",
            "-c",
            "user.email=setup@hivemind.local",
            "commit",
            "--allow-empty",
            "-m",
            "Start tracking this project\n\nCreated by Hivemind when the folder was opened, so changes can be\nkept separate until you choose to ship them. Project files that are\nnot generated or ignored are in this commit.",
        ])?;
        Ok(())
    };
    match sequence() {
        Ok(()) => Ok(()),
        Err(cause) => {
            let remaining = undo_git_setup(root, original_gitignore, !git_dir_existed);
            if remaining.is_empty() {
                Err(GitSetupFailure::untouched(cause))
            } else {
                Err(GitSetupFailure {
                    code: "partial_state",
                    message: cause,
                    remaining,
                })
            }
        }
    }
}

/// Make a folder into a git repository, with an explicit first commit.
///
/// Deliberately NOT a silent `git init && git add -A && git commit`. It refuses
/// on the same grounds `inspect_git_readiness` refuses, re-checked here rather
/// than trusted from the caller -- the readiness answer and the action are two
/// round trips apart, and a file can appear between them.
#[tauri::command]
pub async fn initialize_git(project_path: String) -> Result<GitReadiness, GitSetupFailure> {
    let readiness = inspect_git_readiness(project_path.clone())
        .await
        .map_err(GitSetupFailure::untouched)?;
    if readiness.is_repo {
        return Ok(readiness);
    }
    if let Some(reason) = readiness.refusal {
        return Err(GitSetupFailure::untouched(reason));
    }

    let root = std::path::Path::new(&project_path);
    let run = |args: &[&str]| -> Result<(), String> {
        /* `hidden_command`, not `Command::new`. This was the one production
           spawn in the shell that bypassed it, and `perform_git_setup` makes
           four to six of them -- `--version`, `init`, a `check-ignore` per
           generated directory, `add -A`, `commit` -- so a person pressing one
           button watched several console windows open and close. The helper
           was hardened for the swap process by measuring GetConsoleWindow()
           inside it; nothing carried that to here, because nothing failed. A
           flashing window is not an error, which is exactly why it survived.
           `spawn_hygiene_tests` now refuses a raw spawn structurally instead
           of relying on the next person to notice. */
        let output = hidden_command("git")
            .args(args)
            .current_dir(root)
            .output()
            .map_err(|error| format!("git could not be started: {error}"))?;
        if output.status.success() {
            return Ok(());
        }
        Err(format!(
            "git {} failed: {}",
            args.join(" "),
            String::from_utf8_lossy(&output.stderr).trim()
        ))
    };

    /* Verify git exists before changing a project file. Generated directories
       are the one refusal Hivemind can resolve without guessing: their names
       come from the closed list above, and the sequence verifies git ignores
       every one before staging anything. */
    run(&["--version"]).map_err(GitSetupFailure::untouched)?;
    perform_git_setup(root, &readiness.would_ignore, &run)?;

    inspect_git_readiness(project_path).await.map_err(|error| GitSetupFailure {
        /* The commit exists by this point, so claiming nothing changed would
           be the exact lie this type exists to prevent. */
        code: "partial_state",
        message: format!(
            "the repository was created, but its state could not be re-read: {error}"
        ),
        remaining: vec![".git".to_string()],
    })
}

#[cfg(test)]
mod spawn_hygiene_tests {
    /* Nothing this app starts may show a console window.
     *
     * The rule existed and was applied one process at a time, which is how
     * `initialize_git` came to spawn git five times with a visible window per
     * call: the helper was right there, and using it was a choice each new
     * call site had to remember. A structural check does not need remembering.
     *
     * Comments and test modules are excluded, so explaining the platform
     * detail stays possible and fixtures that spawn `sleep` stay legal. */
    #[test]
    fn no_production_spawn_bypasses_the_hidden_command_helper() {
        let mut offenders: Vec<String> = Vec::new();
        for (name, source) in [
            ("project.rs", include_str!("project.rs")),
            ("main.rs", include_str!("main.rs")),
        ] {
            let mut in_test_module = false;
            let mut brace_depth: i32 = 0;
            for (index, line) in source.lines().enumerate() {
                let trimmed = line.trim_start();
                if trimmed.starts_with("#[cfg(test)]") {
                    in_test_module = true;
                    brace_depth = 0;
                }
                if in_test_module {
                    brace_depth += line.matches('{').count() as i32;
                    brace_depth -= line.matches('}').count() as i32;
                    if brace_depth <= 0 && line.contains('}') {
                        in_test_module = false;
                    }
                    continue;
                }
                if trimmed.starts_with("//") || trimmed.starts_with("/*") || trimmed.starts_with('*') {
                    continue;
                }
                if !line.contains("Command::new") {
                    continue;
                }
                /* The central helper is where the flag is applied. */
                if line.contains("let mut command = Command::new(program)") {
                    continue;
                }
                /* A spawn that sets its own creation flags nearby is already
                   hardened even when it needs a different flag combination. */
                let window: String = source
                    .lines()
                    .skip(index)
                    .take(14)
                    .collect::<Vec<_>>()
                    .join("\n");
                if window.contains("creation_flags") {
                    continue;
                }
                /* A console window is a Windows concept, so a spawn inside a
                   non-Windows branch has nothing to hide. Caught by this test
                   on its first run: `npm_command` hardens the Windows arm and
                   plainly spawns `npm` on the other, which is correct. */
                let all: Vec<&str> = source.lines().collect();
                let from = index.saturating_sub(6);
                let preceding = all[from..index].join("
");
                if preceding.contains("cfg(not(windows))") {
                    continue;
                }
                offenders.push(format!("{name}:{}", index + 1));
            }
        }
        assert!(
            offenders.is_empty(),
            "these spawns can flash a console window; use hidden_command: {offenders:?}"
        );
    }
}

#[cfg(test)]
mod git_readiness_tests {
    use super::*;

    /// A directory no other test can be holding.
    ///
    /// It was keyed on `{name}-{process id}`, and `cargo test` runs every test
    /// in ONE process in parallel -- so two tests that happened to pick the
    /// same name got the same path. Both were called `"ordinary"`. Each one
    /// begins by deleting the directory and ends by deleting it again, so
    /// whichever started second wiped the other's files out from under it:
    /// sometimes between the write and the read (a file missing from
    /// `would_commit`), sometimes before `is_dir` (a flat "that folder does not
    /// exist"). Two symptoms, one cause, about one run in three.
    ///
    /// A counter rather than a rename, because renaming fixes the collision
    /// that happened and leaves the next one to chance.
    fn temp_dir(name: &str) -> std::path::PathBuf {
        static NEXT: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0);
        let unique = NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let dir = std::env::temp_dir().join(format!(
            "hivemind-git-{name}-{}-{unique}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).expect("temp dir");
        dir
    }

    /// The case that was actually live, reproduced exactly.
    ///
    /// The desktop opened `"."` on launch, which for an installed app is its
    /// own installation directory. That folder holds no `.env`, so the
    /// name-list check passed it and the offer to `git init && git add -A`
    /// would have committed the executable, the DLLs and a bundled
    /// `node_modules`. A list refuses what somebody thought to list; this has
    /// to refuse by shape.
    #[test]
    fn an_installed_application_directory_is_refused() {
        let dir = temp_dir("install-dir");
        std::fs::write(dir.join("hivemind_desktop.exe"), "MZ").expect("exe");
        std::fs::write(dir.join("WebView2Loader.dll"), "MZ").expect("dll");
        std::fs::create_dir_all(dir.join("core").join("node_modules")).expect("bundled deps");

        let readiness = tauri::async_runtime::block_on(inspect_git_readiness(
            dir.to_string_lossy().to_string(),
        ))
        .expect("readiness");

        assert!(!readiness.is_repo);
        let refusal = readiness.refusal.expect("an install directory is refused");
        assert!(refusal.contains("built programs"), "{refusal}");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /* ── An instrument failure of its own kind ─────────────────────────────
     *
     * A test for this exact scenario existed, asserted a folder containing only
     * `holiday.jpg`, and passed -- because a lone photo WAS refused. The bug
     * needed a second file: `notes.txt` beside it flipped `has_source` and the
     * folder read as a project.
     *
     * Right scenario, wrong fixture. This is distinct from the failures this
     * project has recorded before -- an assertion that cannot fail, or a test
     * that cannot see the constraint. Here the assertion was capable and the
     * scenario was correct; the SETUP could not produce the condition. A
     * fixture is a claim about what the situation contains, and a fixture
     * missing the one file that matters tests a situation nobody was worried
     * about while reading as though it covered the one they were.
     *
     * The mitigation is in the fixtures below: the photo case now includes the
     * innocuous file that broke it.
     */
    /* The folder that slipped through.
     *
     * Two holiday photos and a shopping list read as a project and were offered
     * a first commit, because `txt` sat in SOURCE_EXTENSIONS and image
     * extensions were in no list at all. A first commit cannot be un-made
     * without rewriting history, which is exactly what somebody who has never
     * used git cannot be asked to do.
     *
     * Proven to bite: put "txt" back in SOURCE_EXTENSIONS and this fails.
     */
    #[test]
    fn a_folder_of_photos_and_a_shopping_list_is_refused_by_name() {
        let dir = temp_dir("photos");
        std::fs::write(dir.join("holiday.jpg"), "not really a jpeg").expect("photo");
        std::fs::write(dir.join("beach.png"), "not really a png").expect("photo");
        std::fs::write(dir.join("notes.txt"), "milk, eggs
").expect("list");

        let readiness = tauri::async_runtime::block_on(inspect_git_readiness(
            dir.to_string_lossy().to_string(),
        ))
        .expect("readiness");

        assert!(readiness.exists);
        assert!(readiness.is_directory);
        let refusal = readiness.refusal.expect("a folder of photos must be refused");
        // It says what it SAW rather than refusing without naming anything.
        assert!(refusal.contains("beach.png"), "{refusal}");
        assert!(refusal.contains("holiday.jpg"), "{refusal}");
        assert!(refusal.contains("cannot be un-made"), "{refusal}");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /* And the costly direction stays open: a real project with assets beside
       the code is a project, and refusing one would be worse than the bug. */
    #[test]
    fn source_with_images_beside_it_is_still_a_project() {
        let dir = temp_dir("source-with-assets");
        std::fs::write(dir.join("index.ts"), "export default 1;
").expect("source");
        std::fs::write(dir.join("logo.png"), "not really a png").expect("asset");
        std::fs::write(dir.join("README.md"), "# hi
").expect("doc");

        let readiness = tauri::async_runtime::block_on(inspect_git_readiness(
            dir.to_string_lossy().to_string(),
        ))
        .expect("readiness");
        assert_eq!(readiness.refusal, None);
        let _ = std::fs::remove_dir_all(&dir);
    }

    /* A documentation repository is a real project, so documents are stated
       rather than refused. */
    #[test]
    fn a_folder_of_documents_is_not_refused() {
        let dir = temp_dir("docs-only");
        std::fs::write(dir.join("README.md"), "# guide
").expect("doc");
        std::fs::write(dir.join("guide.txt"), "how to
").expect("doc");

        let readiness = tauri::async_runtime::block_on(inspect_git_readiness(
            dir.to_string_lossy().to_string(),
        ))
        .expect("readiness");
        assert_eq!(readiness.refusal, None);
        let _ = std::fs::remove_dir_all(&dir);
    }

    /* A missing path and a file used to come back as errors, so the surface
       fell through to its git branch and announced that a folder which did not
       exist was untracked, with step one ticked above it. They are
       classifications now, and they do not mention git. */
    #[test]
    fn a_missing_path_is_classified_rather_than_thrown() {
        let missing = std::env::temp_dir().join("hivemind-no-such-path-anywhere-xyz");
        let _ = std::fs::remove_dir_all(&missing);

        let readiness = tauri::async_runtime::block_on(inspect_git_readiness(
            missing.to_string_lossy().to_string(),
        ))
        .expect("a missing path must classify, not error");

        assert!(!readiness.exists);
        assert!(!readiness.is_directory);
        let refusal = readiness.refusal.expect("a missing path must say so");
        assert!(refusal.contains("nothing at that path"), "{refusal}");
        assert!(!refusal.contains("git"), "{refusal}");
    }

    #[test]
    fn a_file_is_classified_as_a_file_not_a_missing_folder() {
        let dir = temp_dir("a-file");
        let file = dir.join("index.js");
        std::fs::write(&file, "console.log(1);
").expect("source");

        let readiness = tauri::async_runtime::block_on(inspect_git_readiness(
            file.to_string_lossy().to_string(),
        ))
        .expect("a file must classify, not error");

        // The file exists. Saying "that folder does not exist" about a real
        // file names the wrong problem.
        assert!(readiness.exists);
        assert!(!readiness.is_directory);
        let refusal = readiness.refusal.expect("a file must say so");
        assert!(refusal.contains("file, not a folder"), "{refusal}");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn generated_dependencies_are_offered_with_ignore_entries() {
        let dir = temp_dir("deps-only");
        std::fs::create_dir_all(dir.join("node_modules")).expect("deps");
        std::fs::create_dir_all(dir.join("dist")).expect("build output");
        std::fs::write(dir.join("index.js"), "export default 1;\n").expect("source");

        let readiness = tauri::async_runtime::block_on(inspect_git_readiness(
            dir.to_string_lossy().to_string(),
        ))
        .expect("readiness");

        assert_eq!(readiness.refusal, None);
        assert_eq!(readiness.would_ignore, vec!["dist", "node_modules"]);
        assert!(!readiness.would_commit.contains(&"node_modules".to_string()));
        assert!(!readiness.would_commit.contains(&"dist".to_string()));
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn one_action_ignores_generated_directories_and_creates_the_first_commit() {
        let dir = temp_dir("prepare-generated");
        std::fs::create_dir_all(dir.join("node_modules")).expect("deps");
        std::fs::create_dir_all(dir.join("dist")).expect("build output");
        std::fs::write(dir.join("node_modules").join("dependency.js"), "generated\n").expect("dep");
        std::fs::write(dir.join("dist").join("bundle.js"), "generated\n").expect("bundle");
        std::fs::write(dir.join("index.js"), "export default 1;\n").expect("source");

        let result = tauri::async_runtime::block_on(initialize_git(
            dir.to_string_lossy().to_string(),
        ))
        .expect("one-click git setup");
        assert!(result.is_repo);
        let ignore = std::fs::read_to_string(dir.join(".gitignore")).expect("gitignore");
        assert!(ignore.contains("node_modules/"), "{ignore}");
        assert!(ignore.contains("dist/"), "{ignore}");
        let tracked = std::process::Command::new("git")
            .args(["ls-files"])
            .current_dir(&dir)
            .output()
            .expect("git ls-files");
        let tracked = String::from_utf8_lossy(&tracked.stdout);
        assert!(tracked.contains("index.js"), "{tracked}");
        assert!(tracked.contains(".gitignore"), "{tracked}");
        assert!(!tracked.contains("node_modules"), "{tracked}");
        assert!(!tracked.contains("dist/"), "{tracked}");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn a_non_empty_folder_with_no_recognisable_source_is_refused() {
        let dir = temp_dir("no-source");
        std::fs::write(dir.join("holiday.jpg"), "not source").expect("file");

        let readiness = tauri::async_runtime::block_on(inspect_git_readiness(
            dir.to_string_lossy().to_string(),
        ))
        .expect("readiness");

        let refusal = readiness
            .refusal
            .expect("an ambiguous non-empty folder is refused");
        /* This asserted the generic "no source files" sentence. A lone photo is
           now recognised AS a photo and the refusal names it, which is the more
           useful answer -- and the reason this test kept passing while the real
           bug shipped: adding a `notes.txt` beside the photo flipped
           `has_source` to true, because `txt` was in SOURCE_EXTENSIONS. The
           guarantee is that it refuses and says what it saw. */
        assert!(refusal.contains("holiday.jpg"), "{refusal}");
        assert!(
            refusal.contains("pictures, video or audio"),
            "{refusal}"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn an_empty_folder_is_offered_and_one_action_creates_an_empty_first_commit() {
        let dir = temp_dir("empty-project");

        let readiness = tauri::async_runtime::block_on(inspect_git_readiness(
            dir.to_string_lossy().to_string(),
        ))
        .expect("readiness");
        assert!(!readiness.is_repo);
        assert!(readiness.starts_empty);
        assert_eq!(readiness.refusal, None);
        assert!(readiness.would_commit.is_empty());

        let result = tauri::async_runtime::block_on(initialize_git(
            dir.to_string_lossy().to_string(),
        ))
        .expect("one-click empty-project setup");
        assert!(result.is_repo);

        let commit_count = std::process::Command::new("git")
            .args(["rev-list", "--count", "HEAD"])
            .current_dir(&dir)
            .output()
            .expect("git rev-list");
        assert!(commit_count.status.success());
        assert_eq!(String::from_utf8_lossy(&commit_count.stdout).trim(), "1");

        let tracked = std::process::Command::new("git")
            .args(["ls-files"])
            .current_dir(&dir)
            .output()
            .expect("git ls-files");
        assert!(tracked.status.success());
        assert!(
            String::from_utf8_lossy(&tracked.stdout).trim().is_empty(),
            "the greenfield base commit must not invent a project file"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// The check has to be able to say YES, or it is not a check.
    #[test]
    fn an_ordinary_untracked_project_is_offered() {
        let dir = temp_dir("ordinary");
        std::fs::write(dir.join("index.ts"), "export const x = 1;\n").expect("source");
        std::fs::write(dir.join("README.md"), "# a project\n").expect("readme");

        let readiness = tauri::async_runtime::block_on(inspect_git_readiness(
            dir.to_string_lossy().to_string(),
        ))
        .expect("readiness");

        assert!(!readiness.is_repo);
        assert_eq!(readiness.refusal, None);
        assert!(readiness.would_commit.contains(&"index.ts".to_string()));
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn a_folder_holding_a_secret_is_refused_rather_than_committed() {
        // The whole point of refusing: a first commit cannot be un-made without
        // rewriting history, which is exactly what somebody who has never used
        // git cannot be asked to do.
        let dir = temp_dir("secret");
        std::fs::write(dir.join(".env"), "TOKEN=1
").expect("write");
        std::fs::write(dir.join("index.js"), "//
").expect("write");

        let readiness =
            tauri::async_runtime::block_on(inspect_git_readiness(dir.to_string_lossy().to_string()))
                .expect("readiness");
        assert!(!readiness.is_repo);
        let refusal = readiness.refusal.expect("a secret must produce a refusal");
        assert!(refusal.contains(".env"), "the refusal must name the file: {refusal}");

        // And the action refuses too, re-checked rather than trusting the
        // earlier answer -- a file can appear between the two round trips.
        let attempted =
            tauri::async_runtime::block_on(initialize_git(dir.to_string_lossy().to_string()));
        assert!(attempted.is_err(), "initialize_git proceeded past a refusal");
        assert!(!dir.join(".git").exists(), "a repository was created anyway");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// A-07: the sequence used to stop wherever it failed, leaving a
    /// half-made repository and a rewritten .gitignore while the screen said
    /// "Nothing changed." The runner here is real git on a real folder with
    /// exactly one step broken, so the rollback is held to its claim: the
    /// folder must come back byte-identical, and the failure must say so in
    /// its code.
    #[test]
    fn a_failed_setup_puts_the_folder_back_byte_for_byte() {
        let dir = temp_dir("rollback");
        std::fs::create_dir_all(dir.join("node_modules")).expect("deps");
        std::fs::write(dir.join("node_modules").join("dep.js"), "generated\n").expect("dep");
        std::fs::write(dir.join("index.js"), "export default 1;\n").expect("source");
        std::fs::write(dir.join(".gitignore"), "custom-rule\n").expect("prior ignore");

        let real = |args: &[&str]| -> Result<(), String> {
            let output = std::process::Command::new("git")
                .args(args)
                .current_dir(&dir)
                .output()
                .map_err(|error| format!("git could not be started: {error}"))?;
            if output.status.success() {
                Ok(())
            } else {
                Err(format!("git {} failed", args.join(" ")))
            }
        };
        let failing_at_add = |args: &[&str]| -> Result<(), String> {
            if args.first() == Some(&"add") {
                return Err("simulated: git add failed".to_string());
            }
            real(args)
        };

        let failure = perform_git_setup(&dir, &["node_modules".to_string()], &failing_at_add)
            .expect_err("the injected failure must surface");

        assert_eq!(failure.code, "nothing_changed");
        assert!(failure.remaining.is_empty(), "{:?}", failure.remaining);
        assert!(
            !dir.join(".git").exists(),
            "the half-made repository must be removed"
        );
        assert_eq!(
            std::fs::read_to_string(dir.join(".gitignore")).expect("gitignore"),
            "custom-rule\n",
            "the pre-action .gitignore must be restored byte for byte"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn a_failed_setup_where_no_gitignore_existed_leaves_none_behind() {
        let dir = temp_dir("rollback-clean");
        std::fs::create_dir_all(dir.join("node_modules")).expect("deps");
        std::fs::write(dir.join("index.js"), "export default 1;\n").expect("source");

        let failing_at_commit = |args: &[&str]| -> Result<(), String> {
            if args.contains(&"commit") {
                return Err("simulated: git commit failed".to_string());
            }
            let output = std::process::Command::new("git")
                .args(args)
                .current_dir(&dir)
                .output()
                .map_err(|error| format!("git could not be started: {error}"))?;
            if output.status.success() {
                Ok(())
            } else {
                Err(format!("git {} failed", args.join(" ")))
            }
        };

        let failure = perform_git_setup(&dir, &["node_modules".to_string()], &failing_at_commit)
            .expect_err("the injected failure must surface");

        assert_eq!(failure.code, "nothing_changed");
        assert!(
            !dir.join(".gitignore").exists(),
            "a .gitignore this call wrote must not survive its failure"
        );
        assert!(!dir.join(".git").exists());
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// The other branch of the claim: when rollback itself cannot complete,
    /// the answer names what remains instead of asserting cleanliness. A
    /// `.git` that is a FILE cannot be removed by `remove_dir_all`, which is
    /// a deterministic stand-in for a directory held by another process.
    #[test]
    fn a_rollback_that_cannot_complete_names_what_remains() {
        let dir = temp_dir("rollback-stuck");
        std::fs::write(dir.join(".git"), "not a directory").expect("blocker");

        let remaining = undo_git_setup(&dir, None, true);

        assert!(
            remaining.contains(&".git".to_string()),
            "an unremovable leftover must be named: {remaining:?}"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn an_ordinary_folder_is_offered_with_the_files_it_would_commit_named() {
        let dir = temp_dir("ordinary");
        std::fs::write(dir.join("index.js"), "//
").expect("write");
        std::fs::write(dir.join("README.md"), "# x
").expect("write");

        let readiness =
            tauri::async_runtime::block_on(inspect_git_readiness(dir.to_string_lossy().to_string()))
                .expect("readiness");
        assert!(!readiness.is_repo);
        assert!(readiness.refusal.is_none());
        // Named, so the offer can say what it is about to take.
        assert!(readiness.would_commit.contains(&"index.js".to_string()));
        assert!(readiness.would_commit.contains(&"README.md".to_string()));
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn an_existing_repository_is_left_alone() {
        let dir = temp_dir("existing");
        std::fs::create_dir_all(dir.join(".git")).expect("git dir");
        let readiness =
            tauri::async_runtime::block_on(inspect_git_readiness(dir.to_string_lossy().to_string()))
                .expect("readiness");
        assert!(readiness.is_repo);
        assert!(readiness.would_commit.is_empty());
        let _ = std::fs::remove_dir_all(&dir);
    }
}

