//
// This proof gates two irreversible-feeling acts: restarting the daemon after
// an update, and installing a new build over the running one. It has to be
// right in BOTH directions, and the two failures are not symmetric.
//
// Recovering too eagerly restarts into a running job, which is the exact thing
// the detached daemon exists to prevent. Recovering too reluctantly is quieter
// and just as bad in practice: a crash leaves `active` reservations behind
// forever, and a project that can never prove itself idle is one where the
// build bar and the daemon restart are permanently disabled with no way back.
#[cfg(test)]
mod idleness_tests {
    use super::tests::terminate_fixture_process;
    use super::*;
    use std::time::{SystemTime, UNIX_EPOCH};

    fn project_with_reservation(label: &str, status: &str) -> PathBuf {
        project_with_reservation_session(label, status, "run-1")
    }

    fn project_with_reservation_session(label: &str, status: &str, session_id: &str) -> PathBuf {
        let nonce = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
        let project = std::env::temp_dir().join(format!(
            "hivemind-idle-{label}-{}-{nonce}",
            std::process::id()
        ));
        fs::create_dir_all(project.join(".hivemind").join("resource")).unwrap();
        fs::write(
            project.join(".hivemind").join("resource").join("ledger.json"),
            format!(
                r#"{{"version":1,"providers":{{}},"reservations":[{{"reservation_id":"r1","status":"{status}","session_id":"{session_id}"}}]}}"#
            ),
        )
        .unwrap();
        project
    }

    fn record_daemon(project: &Path, pid: u32) {
        fs::write(
            project.join(".hivemind").join("daemon.json"),
            format!(
                r#"{{"version":2,"pid":{pid},"url":"http://127.0.0.1:7777","repo_root":"{}","auth_token":"{}","started_at":"now"}}"#,
                project.to_string_lossy().replace(char::from(92), "/"),
                "T".repeat(43),
            ),
        )
        .unwrap();
    }

    fn record_legacy_daemon(project: &Path, pid: u32) {
        fs::write(
            project.join(".hivemind").join("daemon.json"),
            format!(
                r#"{{"version":1,"pid":{pid},"url":"http://127.0.0.1:7777","repo_root":"{}","started_at":"now"}}"#,
                project.to_string_lossy().replace(char::from(92), "/"),
            ),
        )
        .unwrap();
    }

    fn spawn_sleeper() -> std::process::Child {
        if cfg!(windows) {
            let mut command = hidden_command("powershell");
            command.args(["-NoProfile", "-Command", "Start-Sleep -Seconds 30"]);
            command.spawn().unwrap()
        } else {
            Command::new("sleep").arg("30").spawn().unwrap()
        }
    }

    fn append_trail(project: &Path, lines: &[serde_json::Value]) {
        let log = project.join(".hivemind").join("log");
        fs::create_dir_all(&log).unwrap();
        let mut body = String::new();
        for line in lines {
            body.push_str(&line.to_string());
            body.push('\n');
        }
        let existing = fs::read_to_string(log.join("events.jsonl")).unwrap_or_default();
        fs::write(log.join("events.jsonl"), format!("{existing}{body}")).unwrap();
    }

    fn started_event(task_id: &str) -> serde_json::Value {
        serde_json::json!({
            "ts": "2026-08-21T00:00:00.000Z",
            "type": "task.started",
            "task_id": task_id,
            "data": { "task_id": task_id }
        })
    }

    fn completed_event(task_id: &str) -> serde_json::Value {
        serde_json::json!({
            "ts": "2026-08-21T00:00:02.000Z",
            "type": "task.completed",
            "task_id": task_id,
            "data": { "task_id": task_id, "status": "completed", "changed_files": 0 }
        })
    }

    /* THE DANGEROUS DIRECTION. A daemon that is genuinely running holds
       reservations that are genuinely live, and nothing may read that as safe
       to restart into. */
    #[test]
    fn a_live_daemons_reservations_still_read_as_busy() {
        let project = project_with_reservation("live", "active");
        let child = spawn_sleeper();
        record_daemon(&project, child.id());

        let standing = daemon_work(&project);
        assert_eq!(
            standing.work,
            DaemonWork::Busy,
            "a live daemon with an active reservation must never read as idle: {}",
            standing.detail
        );

        terminate_fixture_process(child.id());
        let _ = fs::remove_dir_all(&project);
    }

    #[test]
    fn legacy_active_work_keeps_the_restart_guard_closed_during_the_auth_upgrade() {
        let project = project_with_reservation("legacy-live", "active");
        let child = spawn_sleeper();
        record_legacy_daemon(&project, child.id());

        let standing = daemon_work(&project);
        assert_ne!(
            standing.work,
            DaemonWork::Idle,
            "legacy active work must never authorize a restart: {}",
            standing.detail
        );

        terminate_fixture_process(child.id());
        let _ = fs::remove_dir_all(&project);
    }

    #[test]
    fn a_live_provider_probe_is_named_as_a_retryable_check() {
        let project = project_with_reservation_session("probe", "active", "probe-worker-grok");
        let child = spawn_sleeper();
        record_daemon(&project, child.id());

        let standing = daemon_work(&project);
        assert_eq!(standing.work, DaemonWork::Busy);
        assert!(
            standing.detail.contains("provider check is still finishing"),
            "the updater must name the transient provider check: {}",
            standing.detail
        );
        assert!(standing.detail.contains("Try again"));

        terminate_fixture_process(child.id());
        let _ = fs::remove_dir_all(&project);
    }

    /* THE OTHER DANGEROUS DIRECTION: a task the trail has not closed is being
       advanced by the live daemon, worktree and all. */
    #[test]
    fn a_live_daemons_running_task_still_reads_as_busy() {
        let project = project_with_reservation("running", "settled");
        fs::create_dir_all(project.join(".hivemind").join("worktrees").join("T-RUN")).unwrap();
        append_trail(&project, &[started_event("T-RUN")]);
        let child = spawn_sleeper();
        record_daemon(&project, child.id());

        let standing = daemon_work(&project);
        assert_eq!(
            standing.work,
            DaemonWork::Busy,
            "a running task's worktree must never read as stale: {}",
            standing.detail
        );
        assert!(standing.detail.contains("T-RUN"), "{}", standing.detail);

        terminate_fixture_process(child.id());
        let _ = fs::remove_dir_all(&project);
    }

    /* And a worktree the trail cannot account for at all is a run that is
       AHEAD, not behind -- a just-created worktree looks exactly like this in
       the moment before its run starts. */
    #[test]
    fn a_live_daemons_unaccounted_worktree_stays_busy() {
        let project = project_with_reservation("unaccounted", "settled");
        fs::create_dir_all(project.join(".hivemind").join("worktrees").join("T-NEW")).unwrap();
        let child = spawn_sleeper();
        record_daemon(&project, child.id());

        let standing = daemon_work(&project);
        assert_eq!(
            standing.work,
            DaemonWork::Busy,
            "an unaccounted worktree must fail toward busy: {}",
            standing.detail
        );

        terminate_fixture_process(child.id());
        let _ = fs::remove_dir_all(&project);
    }

    /* A-37: the artefact-counting proof read a finished task's worktree as
       work forever -- restart and update recovery refused permanently, on a
       project whose run had completed. A task the trail closed owns nothing;
       its worktree is a leftover, named and disregarded. */
    #[test]
    fn a_live_daemons_leftover_worktree_no_longer_blocks_idleness() {
        let project = project_with_reservation("leftover", "settled");
        fs::create_dir_all(project.join(".hivemind").join("worktrees").join("T-003")).unwrap();
        append_trail(&project, &[started_event("T-003"), completed_event("T-003")]);
        let child = spawn_sleeper();
        record_daemon(&project, child.id());

        let standing = daemon_work(&project);
        assert_eq!(
            standing.work,
            DaemonWork::Idle,
            "a finished task's worktree must not close the idleness proof forever: {}",
            standing.detail
        );
        assert!(
            standing.detail.contains("T-003"),
            "the person is told what is being disregarded: {}",
            standing.detail
        );

        terminate_fixture_process(child.id());
        let _ = fs::remove_dir_all(&project);
    }

    /* A history that cannot be read is not evidence of idleness. */
    #[test]
    fn an_unreadable_history_keeps_the_guard_closed() {
        let project = project_with_reservation("unreadable", "settled");
        fs::create_dir_all(project.join(".hivemind").join("worktrees").join("T-X")).unwrap();
        // events.jsonl as a DIRECTORY: open() fails with something other than
        // NotFound, which is the unreadable case, not the empty one.
        fs::create_dir_all(project.join(".hivemind").join("log").join("events.jsonl")).unwrap();
        let child = spawn_sleeper();
        record_daemon(&project, child.id());

        let standing = daemon_work(&project);
        assert_eq!(
            standing.work,
            DaemonWork::Unknown,
            "an unreadable trail must fail closed: {}",
            standing.detail
        );

        terminate_fixture_process(child.id());
        let _ = fs::remove_dir_all(&project);
    }

    /* PL-1: liveness this code cannot determine keeps the guard closed. The
       daemon is provably dead; the worker's pid answers "cannot tell". */
    #[test]
    fn an_uncertain_worker_keeps_the_guard_closed() {
        let project = project_with_reservation("uncertain", "settled");
        fs::create_dir_all(project.join(".hivemind").join("worktrees").join("T-W")).unwrap();
        write_worker_trail(&project, 4242, false);
        record_daemon(&project, 4_294_000_113);

        let daemon_pid = 4_294_000_113u32;
        let standing = daemon_work_with(&project, &move |pid| {
            if pid == Some(daemon_pid) {
                ProcessLiveness::Dead
            } else {
                ProcessLiveness::Unknown
            }
        });
        assert_eq!(
            standing.work,
            DaemonWork::Unknown,
            "EPERM and ambiguity mean alive, and alive keeps the guard closed: {}",
            standing.detail
        );

        let _ = fs::remove_dir_all(&project);
    }

    /* A-39: a pid is a name the OS reuses. The recorded daemon died, Windows
       handed its pid to an unrelated process (a web browser, in the live
       instance), and pid-only liveness read alive-plus-dead-HTTP as an
       unhealthy live daemon that refuses attach forever. A process that
       started long after the record was written cannot be the daemon that
       wrote it -- the sleeper here is real, and the record is backdated to
       two hours before the sleeper was born. */
    #[test]
    fn a_reused_pid_is_not_the_recorded_daemon() {
        let project = project_with_reservation("impostor", "active");
        let stranger = spawn_sleeper();
        record_daemon(&project, stranger.id());
        let record = project.join(".hivemind").join("daemon.json");
        let file = fs::OpenOptions::new().write(true).open(&record).unwrap();
        file.set_modified(SystemTime::now() - Duration::from_secs(7_200))
            .unwrap();
        drop(file);

        let standing = daemon_work(&project);
        assert_eq!(
            standing.work,
            DaemonWork::Idle,
            "a stranger wearing a reused pid must not hold the project: {}",
            standing.detail
        );

        terminate_fixture_process(stranger.id());
        let _ = fs::remove_dir_all(&project);
    }

    /* Workers are spawned detached, so a dead daemon is not evidence that its
       workers died with it. A recorded start with no recorded stop is judged
       by the real process. */
    #[test]
    fn a_dead_daemons_surviving_worker_still_reads_as_busy() {
        let project = project_with_reservation("survivor", "settled");
        fs::create_dir_all(project.join(".hivemind").join("worktrees").join("T-W")).unwrap();
        let worker = spawn_sleeper();
        write_worker_trail(&project, worker.id(), false);
        // The daemon record names a process that is already gone.
        record_daemon(&project, 4_294_000_111);

        let standing = daemon_work(&project);
        assert_eq!(
            standing.work,
            DaemonWork::Busy,
            "a live worker's worktree must never read as stale: {}",
            standing.detail
        );

        terminate_fixture_process(worker.id());
        let _ = fs::remove_dir_all(&project);
    }

    #[test]
    fn a_dead_daemons_stopped_worker_releases_the_guard() {
        let project = project_with_reservation("stopped", "settled");
        fs::create_dir_all(project.join(".hivemind").join("worktrees").join("T-W")).unwrap();
        let worker = spawn_sleeper();
        let pid = worker.id();
        write_worker_trail(&project, pid, true);
        terminate_fixture_process(pid);
        for _ in 0..50 {
            if process_liveness(Some(pid)) == ProcessLiveness::Dead {
                break;
            }
            thread::sleep(Duration::from_millis(100));
        }
        record_daemon(&project, 4_294_000_112);

        let standing = daemon_work(&project);
        assert_eq!(
            standing.work,
            DaemonWork::Idle,
            "a worker the trail stopped holds nothing: {}",
            standing.detail
        );

        let _ = fs::remove_dir_all(&project);
    }

    fn write_worker_trail(project: &Path, pid: u32, stopped: bool) {
        let log = project.join(".hivemind").join("log");
        fs::create_dir_all(&log).unwrap();
        let mut lines = format!(
            "{}\n",
            serde_json::json!({
                "ts": "2026-08-21T00:00:00.000Z",
                "type": "task.worker_process_started",
                "task_id": "T-W",
                "data": { "version": 1, "run_id": "R-1", "tool": "worker", "pid": pid, "process_instance_id": "fixture", "process_group_id": null }
            })
        );
        if stopped {
            lines.push_str(&format!(
                "{}\n",
                serde_json::json!({
                    "ts": "2026-08-21T00:00:01.000Z",
                    "type": "task.worker_process_stopped",
                    "task_id": "T-W",
                    "data": { "version": 1, "run_id": "R-1", "pid": pid, "process_instance_id": "fixture", "adapter_result": "closed" }
                })
            ));
        }
        fs::write(log.join("events.jsonl"), lines).unwrap();
    }

    /* THE RECOVERY DIRECTION. A daemon that died mid-call leaves its
       reservation `active` forever -- nothing settles it, because the thing
       that would settle it is gone. Reading that as busy means the project can
       never prove itself idle again. */
    #[test]
    fn a_dead_daemons_reservations_do_not_block_forever() {
        let project = project_with_reservation("dead", "active");
        let child = spawn_sleeper();
        let pid = child.id();
        record_daemon(&project, pid);
        // Killed mid-reservation, exactly as a crash would leave it.
        terminate_fixture_process(pid);
        for _ in 0..50 {
            if process_liveness(Some(pid)) == ProcessLiveness::Dead {
                break;
            }
            thread::sleep(Duration::from_millis(100));
        }
        assert_eq!(process_liveness(Some(pid)), ProcessLiveness::Dead);

        let standing = daemon_work(&project);
        assert_eq!(
            standing.work,
            DaemonWork::Idle,
            "a dead daemon's leftover reservation must not block forever: {}",
            standing.detail
        );

        let _ = fs::remove_dir_all(&project);
    }

    /* A settled reservation is not work, whoever wrote it. */
    #[test]
    fn settled_reservations_are_not_work() {
        let project = project_with_reservation("settled", "settled");
        assert_eq!(daemon_work(&project).work, DaemonWork::Idle);
        let _ = fs::remove_dir_all(&project);
    }

    /* No daemon record at all: nothing is registered as running this project,
       so a leftover reservation is an orphan rather than live work. The shell
       finds daemons through this record, so one it cannot see is one it would
       start a replacement for anyway. */
    #[test]
    fn reservations_with_no_daemon_record_are_orphans() {
        let project = project_with_reservation("orphan", "active");
        assert_eq!(daemon_work(&project).work, DaemonWork::Idle);
        let _ = fs::remove_dir_all(&project);
    }

    /* Uncertain liveness is NOT idleness. Permission-denied and ambiguous
       probes have to keep the guard closed, or the fail-safe is decorative. */
    #[test]
    fn unknown_liveness_keeps_the_guard_closed() {
        let project = project_with_reservation("unknown", "active");
        // Pid 0 is never a real process and `process_liveness` reports Unknown.
        record_daemon(&project, 0);
        let standing = daemon_work(&project);
        assert_ne!(
            standing.work,
            DaemonWork::Idle,
            "uncertain liveness must not be read as idle: {}",
            standing.detail
        );
        let _ = fs::remove_dir_all(&project);
    }
}
